package com.payshield.service; import com.payshield.repo.OutboxRepository; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class OutboxPublisher {private static final Logger log=LoggerFactory.getLogger(OutboxPublisher.class);private final OutboxRepository events; public OutboxPublisher(OutboxRepository events){this.events=events;} @Scheduled(fixedDelay=5000) @Transactional public void publish(){events.findTop20ByPublishedAtIsNullOrderByCreatedAtAsc().forEach(e->{log.info("Published event {} ({})",e.getId(),e.getEventType());e.published();});}}
